import { useMemo, useState } from "react";
import { Plus, Pencil, Home, Users, Trash2, Wrench, Check, X } from "lucide-react";
import { useDb } from "../db/useDb";
import { consultar, executar } from "../db/connection";
import type {
  ContratoLocacao,
  Imovel,
  Inquilino,
  ItemInventarioBem,
  Manutencao,
  RegimePatrimonial,
  StatusManutencao,
  TipoImovel,
} from "../domain/types";
import { formatarMoeda } from "../domain/formatarMoeda";
import { registrarLog, resumirDiferenca } from "../domain/auditoria/logAlteracoes";
import { obterEntidadeAtiva } from "../domain/erp/entidadeLegal";
import {
  cadastrarInquilino,
  listarInquilinosPorImovel,
  removerInquilino,
  agendarManutencao,
  listarManutencoesPorImovel,
  iniciarManutencao,
  concluirManutencao,
  cancelarManutencao,
  obterResumoDespesasAgendadasImovel,
} from "../domain/erp/gestaoOperacionalImovel";

const ROTULO_STATUS_MANUTENCAO: Record<StatusManutencao, string> = {
  agendada: "Agendada",
  em_andamento: "Em andamento",
  concluida: "Concluída",
  cancelada: "Cancelada",
};

const PILL_STATUS_MANUTENCAO: Record<StatusManutencao, string> = {
  agendada: "",
  em_andamento: "warning",
  concluida: "good",
  cancelada: "",
};

interface RascunhoInquilino {
  nome: string;
  cpf_cnpj: string;
  telefone: string;
  email: string;
  contrato_id: string;
  observacoes: string;
}

const RASCUNHO_INQUILINO_VAZIO: RascunhoInquilino = {
  nome: "",
  cpf_cnpj: "",
  telefone: "",
  email: "",
  contrato_id: "",
  observacoes: "",
};

interface RascunhoManutencao {
  tipo: string;
  descricao: string;
  data_agendada: string;
  custo: string;
  observacoes: string;
}

const RASCUNHO_MANUTENCAO_VAZIO: RascunhoManutencao = {
  tipo: "",
  descricao: "",
  data_agendada: "",
  custo: "",
  observacoes: "",
};

const ROTULO_TIPO: Record<TipoImovel, string> = {
  apartamento: "Apartamento",
  kitnet: "Kitnet",
  sala_comercial: "Sala comercial",
  vaga_garagem: "Vaga de garagem",
  outro: "Outro",
};

interface FormularioImovel {
  id: number | null;
  apelido: string;
  tipo: TipoImovel;
  cidade: string;
  endereco: string;
  fracao_ideal: string;
  area_m2: string;
  financiado: boolean;
  uso_pessoal: boolean;
  matricula: string;
  matricula_mae: string;
  valor_aquisicao: string;
  valor_venal_atual: string;
  data_avaliacao_venal: string;
  regime_patrimonial: RegimePatrimonial;
  proprietario_nome: string;
  co_titular_nome: string;
}

const FORM_VAZIO: FormularioImovel = {
  id: null,
  apelido: "",
  tipo: "apartamento",
  cidade: "",
  endereco: "",
  fracao_ideal: "",
  area_m2: "",
  financiado: false,
  uso_pessoal: false,
  matricula: "",
  matricula_mae: "",
  valor_aquisicao: "",
  valor_venal_atual: "",
  data_avaliacao_venal: "",
  regime_patrimonial: "proprio",
  proprietario_nome: "",
  co_titular_nome: "",
};

export function ImoveisView() {
  const { db, versao, persistir } = useDb();
  const [form, setForm] = useState<FormularioImovel | null>(null);
  const [novoItemInventario, setNovoItemInventario] = useState({ descricao: "", valor_reposicao: "", data_vistoria: "" });
  const [abaOperacional, setAbaOperacional] = useState<"inquilinos" | "manutencoes">("inquilinos");
  const [rascunhoInquilino, setRascunhoInquilino] = useState<RascunhoInquilino>(RASCUNHO_INQUILINO_VAZIO);
  const [rascunhoManutencao, setRascunhoManutencao] = useState<RascunhoManutencao>(RASCUNHO_MANUTENCAO_VAZIO);
  const [concluindoId, setConcluindoId] = useState<number | null>(null);
  const [dataConclusao, setDataConclusao] = useState("");
  const [custoConclusao, setCustoConclusao] = useState("");
  const [cancelandoManutencaoId, setCancelandoManutencaoId] = useState<number | null>(null);
  const [motivoCancelamentoManutencao, setMotivoCancelamentoManutencao] = useState("");

  const imoveis = useMemo<Imovel[]>(
    () => (db ? consultar<Imovel>(db, "SELECT * FROM imoveis ORDER BY COALESCE(cidade, 'zzz'), apelido") : []),
    [db, versao],
  );

  const entidade = useMemo(() => (db ? obterEntidadeAtiva(db) : null), [db, versao]);

  const formId = form?.id ?? null;
  const itensInventario = useMemo<ItemInventarioBem[]>(
    () => (db && formId ? consultar<ItemInventarioBem>(db, "SELECT * FROM imovel_inventario_bens WHERE imovel_id = ? ORDER BY id", [formId]) : []),
    [db, versao, formId],
  );

  const contratosDoImovel = useMemo<ContratoLocacao[]>(
    () =>
      db && formId
        ? consultar<ContratoLocacao>(db, "SELECT * FROM contratos_locacao WHERE imovel_id = ? ORDER BY data_inicio DESC", [formId])
        : [],
    [db, versao, formId],
  );

  const inquilinos = useMemo<Inquilino[]>(
    () => (db && formId ? listarInquilinosPorImovel(db, formId) : []),
    [db, versao, formId],
  );

  const manutencoes = useMemo<Manutencao[]>(
    () => (db && formId ? listarManutencoesPorImovel(db, formId) : []),
    [db, versao, formId],
  );

  const resumoDespesas = useMemo(
    () => (db && formId && entidade ? obterResumoDespesasAgendadasImovel(db, entidade.id, formId) : null),
    [db, versao, formId, entidade],
  );

  const cidadesConhecidas = useMemo(
    () => Array.from(new Set(imoveis.map((i) => i.cidade).filter((c): c is string => !!c))).sort(),
    [imoveis],
  );

  function abrirNovo() {
    setForm(FORM_VAZIO);
  }

  function abrirEdicao(imovel: Imovel) {
    setForm({
      id: imovel.id,
      apelido: imovel.apelido,
      tipo: imovel.tipo,
      cidade: imovel.cidade ?? "",
      endereco: imovel.endereco ?? "",
      fracao_ideal: imovel.fracao_ideal?.toString() ?? "",
      area_m2: imovel.area_m2?.toString() ?? "",
      financiado: imovel.financiado === 1,
      uso_pessoal: imovel.uso_pessoal === 1,
      matricula: imovel.matricula ?? "",
      matricula_mae: imovel.matricula_mae ?? "",
      valor_aquisicao: imovel.valor_aquisicao?.toString() ?? "",
      valor_venal_atual: imovel.valor_venal_atual?.toString() ?? "",
      data_avaliacao_venal: imovel.data_avaliacao_venal ?? "",
      regime_patrimonial: imovel.regime_patrimonial,
      proprietario_nome: imovel.proprietario_nome ?? "",
      co_titular_nome: imovel.co_titular_nome ?? "",
    });
  }

  async function salvar() {
    if (!db || !form || form.apelido.trim() === "") return;
    const fracaoIdeal = form.fracao_ideal.trim() === "" ? null : Number.parseFloat(form.fracao_ideal.replace(",", "."));
    if (fracaoIdeal !== null && fracaoIdeal <= 0) {
      alert("Fração ideal precisa ser um número maior que zero (ex: 0,08) — deixe em branco se não souber.");
      return;
    }
    // Aviso não-bloqueante: se a soma das frações já cadastradas para o mesmo prédio
    // (matricula_mae) passar de 1 (100%), o rateio por fracao_ideal fica matematicamente
    // consistente (sempre soma 100% entre os imóveis SELECIONADOS na tela de rateio) mas
    // substantivamente errado se alguém esquecer uma unidade — sem essa soma nunca aparecer
    // como inconsistência, o erro fica invisível (achado de auditoria adversarial). Não
    // bloqueia porque o prédio pode legitimamente ainda estar sendo cadastrado aos poucos.
    if (fracaoIdeal !== null && form.matricula_mae.trim() !== "") {
      const somaOutrosImoveis = imoveis
        .filter((i) => i.id !== form.id && i.matricula_mae === form.matricula_mae.trim())
        .reduce((acc, i) => acc + (i.fracao_ideal ?? 0), 0);
      const somaTotal = somaOutrosImoveis + fracaoIdeal;
      if (somaTotal > 1.01) {
        const continuar = confirm(
          `A soma das frações ideais já cadastradas para a matrícula-mãe "${form.matricula_mae.trim()}" ficaria em ` +
            `${(somaTotal * 100).toFixed(1)}% — mais que 100%. Confira se não há erro de digitação ou unidade ` +
            "esquecida antes de continuar. Salvar mesmo assim?",
        );
        if (!continuar) return;
      }
    }
    const areaM2 = form.area_m2.trim() === "" ? null : Number.parseFloat(form.area_m2.replace(",", "."));
    const valorAquisicao = form.valor_aquisicao.trim() === "" ? null : Number.parseFloat(form.valor_aquisicao.replace(",", "."));
    const valorVenal = form.valor_venal_atual.trim() === "" ? null : Number.parseFloat(form.valor_venal_atual.replace(",", "."));

    const camposComuns = [
      form.apelido.trim(),
      form.tipo,
      form.cidade.trim() || null,
      form.endereco.trim() || null,
      fracaoIdeal,
      areaM2,
      form.financiado ? 1 : 0,
      form.uso_pessoal ? 1 : 0,
      form.matricula.trim() || null,
      form.matricula_mae.trim() || null,
      valorAquisicao,
      valorVenal,
      form.data_avaliacao_venal || null,
      form.regime_patrimonial,
      form.regime_patrimonial === "gestao_terceiros" ? form.proprietario_nome.trim() || null : null,
      form.regime_patrimonial === "proprio" ? form.co_titular_nome.trim() || null : null,
    ];

    // Snapshot ANTES da escrita — precisa vir antes do INSERT/UPDATE para capturar o estado
    // anterior de verdade (trilha de auditoria de edição, achado de auditoria de completude:
    // sem isso não havia como provar que valor_venal_atual/co_titular_nome/etc. não foram
    // alterados depois do fato).
    const dadosAnteriores = form.id !== null ? (consultar<Imovel>(db, "SELECT * FROM imoveis WHERE id = ?", [form.id])[0] as unknown as Record<string, unknown>) ?? null : null;

    if (form.id === null) {
      executar(
        db,
        `INSERT INTO imoveis (apelido, tipo, cidade, endereco, fracao_ideal, area_m2, financiado, uso_pessoal,
           matricula, matricula_mae, valor_aquisicao, valor_venal_atual, data_avaliacao_venal, regime_patrimonial, proprietario_nome, co_titular_nome)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        camposComuns,
      );
    } else {
      executar(
        db,
        `UPDATE imoveis SET apelido = ?, tipo = ?, cidade = ?, endereco = ?, fracao_ideal = ?, area_m2 = ?, financiado = ?, uso_pessoal = ?,
           matricula = ?, matricula_mae = ?, valor_aquisicao = ?, valor_venal_atual = ?, data_avaliacao_venal = ?, regime_patrimonial = ?, proprietario_nome = ?, co_titular_nome = ?
         WHERE id = ?`,
        [...camposComuns, form.id],
      );
    }

    const idRegistro = form.id ?? consultar<{ id: number }>(db, "SELECT last_insert_rowid() AS id")[0].id;
    const dadosNovos = consultar<Imovel>(db, "SELECT * FROM imoveis WHERE id = ?", [idRegistro])[0] as unknown as Record<string, unknown>;
    registrarLog(db, "imoveis", idRegistro, form.id === null ? "criacao" : "edicao", resumirDiferenca(dadosAnteriores, dadosNovos), dadosAnteriores, dadosNovos);

    await persistir();
    setForm(null);
  }

  async function adicionarItemInventario() {
    if (!db || !form?.id || novoItemInventario.descricao.trim() === "") return;
    executar(
      db,
      "INSERT INTO imovel_inventario_bens (imovel_id, descricao, valor_reposicao, data_vistoria) VALUES (?, ?, ?, ?)",
      [
        form.id,
        novoItemInventario.descricao.trim(),
        novoItemInventario.valor_reposicao.trim() === "" ? null : Number.parseFloat(novoItemInventario.valor_reposicao.replace(",", ".")),
        novoItemInventario.data_vistoria || null,
      ],
    );
    await persistir();
    setNovoItemInventario({ descricao: "", valor_reposicao: "", data_vistoria: "" });
  }
  async function removerItemInventario(itemId: number) {
    if (!db) return;
    executar(db, "DELETE FROM imovel_inventario_bens WHERE id = ?", [itemId]);
    await persistir();
  }

  async function adicionarInquilino() {
    if (!db || !form?.id || rascunhoInquilino.nome.trim() === "") return;
    const resultado = cadastrarInquilino(db, {
      imovel_id: form.id,
      nome: rascunhoInquilino.nome,
      cpf_cnpj: rascunhoInquilino.cpf_cnpj || undefined,
      telefone: rascunhoInquilino.telefone || undefined,
      email: rascunhoInquilino.email || undefined,
      contrato_id: rascunhoInquilino.contrato_id ? Number(rascunhoInquilino.contrato_id) : undefined,
      observacoes: rascunhoInquilino.observacoes || undefined,
    });
    if (!resultado.sucesso) {
      alert(resultado.mensagem);
      return;
    }
    await persistir();
    setRascunhoInquilino(RASCUNHO_INQUILINO_VAZIO);
  }

  async function removerInquilinoCadastrado(id: number) {
    if (!db) return;
    const resultado = removerInquilino(db, id);
    if (!resultado.sucesso) {
      alert(resultado.mensagem);
      return;
    }
    await persistir();
  }

  async function adicionarManutencao() {
    if (!db || !form?.id || rascunhoManutencao.tipo.trim() === "" || rascunhoManutencao.descricao.trim() === "" || !rascunhoManutencao.data_agendada) {
      return;
    }
    const resultado = agendarManutencao(db, {
      imovel_id: form.id,
      tipo: rascunhoManutencao.tipo,
      descricao: rascunhoManutencao.descricao,
      data_agendada: rascunhoManutencao.data_agendada,
      custo: rascunhoManutencao.custo.trim() === "" ? undefined : Number.parseFloat(rascunhoManutencao.custo.replace(",", ".")),
      observacoes: rascunhoManutencao.observacoes || undefined,
    });
    if (!resultado.sucesso) {
      alert(resultado.mensagem);
      return;
    }
    await persistir();
    setRascunhoManutencao(RASCUNHO_MANUTENCAO_VAZIO);
  }

  async function iniciarManutencaoAgendada(id: number) {
    if (!db) return;
    const resultado = iniciarManutencao(db, id);
    if (!resultado.sucesso) {
      alert(resultado.mensagem);
      return;
    }
    await persistir();
  }

  function abrirConclusaoManutencao(m: Manutencao) {
    setCancelandoManutencaoId(null);
    setConcluindoId(m.id);
    setDataConclusao(new Date().toISOString().slice(0, 10));
    setCustoConclusao(m.custo !== undefined && m.custo !== null ? String(m.custo) : "");
  }

  async function confirmarConclusaoManutencao() {
    if (!db || concluindoId === null || !dataConclusao) return;
    const resultado = concluirManutencao(
      db,
      concluindoId,
      dataConclusao,
      custoConclusao.trim() === "" ? undefined : Number.parseFloat(custoConclusao.replace(",", ".")),
    );
    if (!resultado.sucesso) {
      alert(resultado.mensagem);
      return;
    }
    await persistir();
    setConcluindoId(null);
  }

  function abrirCancelamentoManutencao(id: number) {
    setConcluindoId(null);
    setCancelandoManutencaoId(id);
    setMotivoCancelamentoManutencao("");
  }

  async function confirmarCancelamentoManutencao() {
    if (!db || cancelandoManutencaoId === null) return;
    const resultado = cancelarManutencao(db, cancelandoManutencaoId, motivoCancelamentoManutencao);
    if (!resultado.sucesso) {
      alert(resultado.mensagem);
      return;
    }
    await persistir();
    setCancelandoManutencaoId(null);
  }

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
        <h2 className="section-title">Imóveis ({imoveis.length})</h2>
        <button className="btn primary" onClick={abrirNovo}>
          <Plus size={14} /> Novo imóvel
        </button>
      </div>
      <p style={{ maxWidth: "68ch", color: "var(--ink-soft)", fontSize: 13.5, marginBottom: 18 }}>
        Cadastre aqui seus imóveis reais — cidade agrupa relatórios e rateio por região (ex: Floripa, Curitiba);
        marcar "uso pessoal" (residência própria, não é aluguel) tira o imóvel do DRE da atividade de locação por
        padrão, mantendo suas despesas visíveis separadamente.
      </p>

      {form && (
        <div className="card" style={{ marginBottom: 20 }}>
          <h3 style={{ fontSize: 15, marginBottom: 12 }}>{form.id === null ? "Novo imóvel" : "Editar imóvel"}</h3>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))", gap: 10, marginBottom: 12 }}>
            <label style={{ fontSize: 12, color: "var(--ink-soft)" }}>
              Apelido *
              <input className="btn" style={{ cursor: "text", width: "100%", marginTop: 4 }} value={form.apelido} onChange={(e) => setForm({ ...form, apelido: e.target.value })} />
            </label>
            <label style={{ fontSize: 12, color: "var(--ink-soft)" }}>
              Tipo
              <select className="btn" style={{ width: "100%", marginTop: 4 }} value={form.tipo} onChange={(e) => setForm({ ...form, tipo: e.target.value as TipoImovel })}>
                {Object.entries(ROTULO_TIPO).map(([valor, rotulo]) => (
                  <option key={valor} value={valor}>{rotulo}</option>
                ))}
              </select>
            </label>
            <label style={{ fontSize: 12, color: "var(--ink-soft)" }}>
              Cidade / grupo
              <input
                className="btn" style={{ cursor: "text", width: "100%", marginTop: 4 }}
                list="cidades-conhecidas" value={form.cidade}
                onChange={(e) => setForm({ ...form, cidade: e.target.value })}
                placeholder="ex: Florianópolis"
              />
              <datalist id="cidades-conhecidas">
                {cidadesConhecidas.map((c) => <option key={c} value={c} />)}
              </datalist>
            </label>
            <label style={{ fontSize: 12, color: "var(--ink-soft)" }}>
              Endereço
              <input className="btn" style={{ cursor: "text", width: "100%", marginTop: 4 }} value={form.endereco} onChange={(e) => setForm({ ...form, endereco: e.target.value })} />
            </label>
            <label style={{ fontSize: 12, color: "var(--ink-soft)" }}>
              Fração ideal (0-1)
              <input className="btn" style={{ cursor: "text", width: "100%", marginTop: 4 }} value={form.fracao_ideal} onChange={(e) => setForm({ ...form, fracao_ideal: e.target.value })} placeholder="ex: 0,08" />
            </label>
            <label style={{ fontSize: 12, color: "var(--ink-soft)" }}>
              Área (m²)
              <input className="btn" style={{ cursor: "text", width: "100%", marginTop: 4 }} value={form.area_m2} onChange={(e) => setForm({ ...form, area_m2: e.target.value })} placeholder="ex: 72" />
            </label>
          </div>
          <div style={{ display: "flex", gap: 18, marginBottom: 14 }}>
            <label style={{ display: "flex", gap: 6, alignItems: "center", fontSize: 13 }}>
              <input type="checkbox" checked={form.financiado} onChange={(e) => setForm({ ...form, financiado: e.target.checked })} />
              Financiado
            </label>
            <label style={{ display: "flex", gap: 6, alignItems: "center", fontSize: 13 }}>
              <input type="checkbox" checked={form.uso_pessoal} onChange={(e) => setForm({ ...form, uso_pessoal: e.target.checked })} />
              Uso pessoal (residência própria, fora do DRE da atividade)
            </label>
          </div>

          <div style={{ fontSize: 12, textTransform: "uppercase", color: "var(--ink-soft)", marginBottom: 6, fontWeight: 600 }}>
            Patrimônio (matrícula e avaliação)
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))", gap: 10, marginBottom: 12 }}>
            <label style={{ fontSize: 12, color: "var(--ink-soft)" }}>
              Matrícula
              <input className="btn" style={{ cursor: "text", width: "100%", marginTop: 4 }} value={form.matricula} onChange={(e) => setForm({ ...form, matricula: e.target.value })} />
            </label>
            <label style={{ fontSize: 12, color: "var(--ink-soft)" }}>
              Matrícula-mãe (se agrupada)
              <input className="btn" style={{ cursor: "text", width: "100%", marginTop: 4 }} value={form.matricula_mae} onChange={(e) => setForm({ ...form, matricula_mae: e.target.value })} />
            </label>
            <label style={{ fontSize: 12, color: "var(--ink-soft)" }}>
              Valor de aquisição (R$)
              <input className="btn" style={{ cursor: "text", width: "100%", marginTop: 4 }} value={form.valor_aquisicao} onChange={(e) => setForm({ ...form, valor_aquisicao: e.target.value })} />
            </label>
            <label style={{ fontSize: 12, color: "var(--ink-soft)" }}>
              Valor venal atual (R$)
              <input className="btn" style={{ cursor: "text", width: "100%", marginTop: 4 }} value={form.valor_venal_atual} onChange={(e) => setForm({ ...form, valor_venal_atual: e.target.value })} />
            </label>
            <label style={{ fontSize: 12, color: "var(--ink-soft)" }}>
              Data da avaliação
              <input type="date" className="btn" style={{ width: "100%", marginTop: 4 }} value={form.data_avaliacao_venal} onChange={(e) => setForm({ ...form, data_avaliacao_venal: e.target.value })} />
            </label>
            <label style={{ fontSize: 12, color: "var(--ink-soft)" }}>
              Regime patrimonial
              <select className="btn" style={{ width: "100%", marginTop: 4 }} value={form.regime_patrimonial} onChange={(e) => setForm({ ...form, regime_patrimonial: e.target.value as RegimePatrimonial })}>
                <option value="proprio">Próprio (entra no patrimônio líquido)</option>
                <option value="gestao_terceiros">Gestão de terceiros (fora do PL, só fluxo de caixa)</option>
              </select>
            </label>
            {form.regime_patrimonial === "gestao_terceiros" && (
              <label style={{ fontSize: 12, color: "var(--ink-soft)" }}>
                Proprietário
                <input className="btn" style={{ cursor: "text", width: "100%", marginTop: 4 }} value={form.proprietario_nome} onChange={(e) => setForm({ ...form, proprietario_nome: e.target.value })} placeholder="ex: Avani" />
              </label>
            )}
            {form.regime_patrimonial === "proprio" && (
              <label style={{ fontSize: 12, color: "var(--ink-soft)" }}>
                Copropriedade (opcional — só se houver co-titular real)
                <input
                  className="btn"
                  style={{ cursor: "text", width: "100%", marginTop: 4 }}
                  value={form.co_titular_nome}
                  onChange={(e) => setForm({ ...form, co_titular_nome: e.target.value })}
                  placeholder="ex: Avani — percentual a confirmar"
                />
                <span style={{ display: "block", fontSize: 11, marginTop: 3, lineHeight: 1.4 }}>
                  Preencha só o nome — o sistema nunca estima o percentual de cada titular. O
                  imóvel continua contando 100% no patrimônio líquido até você confirmar a
                  divisão real (matrícula/escritura) e decidir como tratar; enquanto isso, fica
                  sinalizado como pendência em Pendências.
                </span>
              </label>
            )}
          </div>

          {form.id !== null && (
            <div style={{ marginBottom: 16 }}>
              <div style={{ fontSize: 12, textTransform: "uppercase", color: "var(--ink-soft)", marginBottom: 6, fontWeight: 600 }}>
                Inventário de bens (opcional)
              </div>
              <p style={{ fontSize: 11.5, color: "var(--ink-soft)", margin: "0 0 8px", maxWidth: "68ch" }}>
                Mobiliário e equipamentos entregues com o imóvel (o mesmo conteúdo do "Relação e
                Inventário de Bens" que contratos reais anexam na vistoria de entrada), com valor
                de reposição de referência — vira a base do Relatório de Apuração de Débitos (RAD)
                gerado em Depósitos caução na saída do locatário. Só documenta o que estava lá;
                nunca deduz nada da caução sozinho.
              </p>
              {itensInventario.length > 0 && (
                <div className="table-wrap" style={{ marginBottom: 8 }}>
                  <table className="data-table">
                    <thead>
                      <tr><th>Item</th><th className="num">Valor de reposição</th><th>Vistoria</th><th></th></tr>
                    </thead>
                    <tbody>
                      {itensInventario.map((item) => (
                        <tr key={item.id}>
                          <td>{item.descricao}</td>
                          <td className="num">{item.valor_reposicao !== undefined && item.valor_reposicao !== null ? formatarMoeda(item.valor_reposicao) : "—"}</td>
                          <td>{item.data_vistoria ?? "—"}</td>
                          <td>
                            <button className="btn" style={{ padding: "3px 6px" }} onClick={() => removerItemInventario(item.id)}><Trash2 size={12} /></button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
              <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                <input
                  className="btn" style={{ cursor: "text", flex: 1, minWidth: 220 }}
                  placeholder="Item (ex: Ar-condicionado split)"
                  value={novoItemInventario.descricao}
                  onChange={(e) => setNovoItemInventario({ ...novoItemInventario, descricao: e.target.value })}
                />
                <input
                  className="btn" style={{ cursor: "text", width: 130 }}
                  placeholder="Valor (R$)"
                  value={novoItemInventario.valor_reposicao}
                  onChange={(e) => setNovoItemInventario({ ...novoItemInventario, valor_reposicao: e.target.value })}
                />
                <input
                  type="date" className="btn"
                  value={novoItemInventario.data_vistoria}
                  onChange={(e) => setNovoItemInventario({ ...novoItemInventario, data_vistoria: e.target.value })}
                />
                <button className="btn" disabled={novoItemInventario.descricao.trim() === ""} onClick={adicionarItemInventario}>
                  <Plus size={13} />
                </button>
              </div>
            </div>
          )}

          {form.id !== null && (
            <div style={{ marginBottom: 16 }}>
              <div style={{ fontSize: 12, textTransform: "uppercase", color: "var(--ink-soft)", marginBottom: 6, fontWeight: 600 }}>
                Gestão operacional
              </div>

              {resumoDespesas && (
                <div className="kpi-grid" style={{ marginBottom: 10 }}>
                  <div className="kpi-tile">
                    <div className="label">Despesas atrasadas</div>
                    <div className={`value ${resumoDespesas.total_atrasado > 0 ? "critical" : ""}`}>{formatarMoeda(resumoDespesas.total_atrasado)}</div>
                    <div style={{ fontSize: 11.5, color: "var(--ink-soft)" }}>{resumoDespesas.quantidade_atrasada} conta(s)</div>
                  </div>
                  <div className="kpi-tile">
                    <div className="label">Despesas a vencer</div>
                    <div className="value">{formatarMoeda(resumoDespesas.total_pendente)}</div>
                    <div style={{ fontSize: 11.5, color: "var(--ink-soft)" }}>{resumoDespesas.quantidade_pendente} conta(s)</div>
                  </div>
                </div>
              )}
              {!entidade && (
                <p style={{ fontSize: 11.5, color: "var(--ink-soft)", marginBottom: 10 }}>
                  Cadastre a entidade titular para ver o resumo de despesas agendadas deste imóvel.
                </p>
              )}

              <div style={{ display: "flex", gap: 6, marginBottom: 10 }}>
                <button
                  className={`btn ${abaOperacional === "inquilinos" ? "primary" : ""}`}
                  onClick={() => setAbaOperacional("inquilinos")}
                >
                  <Users size={13} /> Inquilinos ({inquilinos.length})
                </button>
                <button
                  className={`btn ${abaOperacional === "manutencoes" ? "primary" : ""}`}
                  onClick={() => setAbaOperacional("manutencoes")}
                >
                  <Wrench size={13} /> Manutenções ({manutencoes.length})
                </button>
              </div>

              {abaOperacional === "inquilinos" && (
                <div>
                  {inquilinos.length > 0 && (
                    <div className="table-wrap" style={{ marginBottom: 8 }}>
                      <table className="data-table">
                        <thead>
                          <tr><th>Nome</th><th>Contato</th><th>Contrato</th><th></th></tr>
                        </thead>
                        <tbody>
                          {inquilinos.map((inq) => (
                            <tr key={inq.id}>
                              <td>
                                {inq.nome}
                                {inq.cpf_cnpj && <div style={{ fontSize: 11.5, color: "var(--ink-soft)" }}>{inq.cpf_cnpj}</div>}
                              </td>
                              <td style={{ fontSize: 12.5 }}>
                                {inq.telefone ?? "—"}
                                {inq.email && <div style={{ fontSize: 11.5, color: "var(--ink-soft)" }}>{inq.email}</div>}
                              </td>
                              <td>
                                {inq.contrato_id ? (
                                  <span className="pill good">contrato #{inq.contrato_id}</span>
                                ) : (
                                  <span className="pill" title="Sem contrato vigente ligado">sem contrato</span>
                                )}
                              </td>
                              <td>
                                <button className="btn" style={{ padding: "3px 6px" }} onClick={() => removerInquilinoCadastrado(inq.id)}>
                                  <Trash2 size={12} />
                                </button>
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  )}
                  <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(160px, 1fr))", gap: 6, marginBottom: 6 }}>
                    <input
                      className="btn" style={{ cursor: "text" }}
                      placeholder="Nome *"
                      value={rascunhoInquilino.nome}
                      onChange={(e) => setRascunhoInquilino({ ...rascunhoInquilino, nome: e.target.value })}
                    />
                    <input
                      className="btn" style={{ cursor: "text" }}
                      placeholder="CPF/CNPJ"
                      value={rascunhoInquilino.cpf_cnpj}
                      onChange={(e) => setRascunhoInquilino({ ...rascunhoInquilino, cpf_cnpj: e.target.value })}
                    />
                    <input
                      className="btn" style={{ cursor: "text" }}
                      placeholder="Telefone"
                      value={rascunhoInquilino.telefone}
                      onChange={(e) => setRascunhoInquilino({ ...rascunhoInquilino, telefone: e.target.value })}
                    />
                    <input
                      className="btn" style={{ cursor: "text" }}
                      placeholder="E-mail"
                      value={rascunhoInquilino.email}
                      onChange={(e) => setRascunhoInquilino({ ...rascunhoInquilino, email: e.target.value })}
                    />
                    <select
                      className="btn"
                      value={rascunhoInquilino.contrato_id}
                      onChange={(e) => setRascunhoInquilino({ ...rascunhoInquilino, contrato_id: e.target.value })}
                    >
                      <option value="">Contrato vigente (opcional)</option>
                      {contratosDoImovel.map((c) => (
                        <option key={c.id} value={c.id}>
                          #{c.id} · {c.locatario} {c.data_fim ? `(até ${c.data_fim})` : "(vigente)"}
                        </option>
                      ))}
                    </select>
                  </div>
                  <div style={{ display: "flex", gap: 6 }}>
                    <input
                      className="btn" style={{ cursor: "text", flex: 1 }}
                      placeholder="Observações"
                      value={rascunhoInquilino.observacoes}
                      onChange={(e) => setRascunhoInquilino({ ...rascunhoInquilino, observacoes: e.target.value })}
                    />
                    <button className="btn" disabled={rascunhoInquilino.nome.trim() === ""} onClick={adicionarInquilino}>
                      <Plus size={13} /> Cadastrar
                    </button>
                  </div>
                </div>
              )}

              {abaOperacional === "manutencoes" && (
                <div>
                  {manutencoes.length > 0 && (
                    <div className="table-wrap" style={{ marginBottom: 8 }}>
                      <table className="data-table">
                        <thead>
                          <tr><th>Tipo</th><th>Descrição</th><th>Agendada</th><th className="num">Custo</th><th>Status</th><th></th></tr>
                        </thead>
                        <tbody>
                          {manutencoes.map((m) => (
                            <>
                              <tr key={m.id}>
                                <td>{m.tipo}</td>
                                <td style={{ fontSize: 12.5 }}>{m.descricao}</td>
                                <td>{m.data_agendada}{m.data_conclusao ? <div style={{ fontSize: 11.5, color: "var(--ink-soft)" }}>concluída {m.data_conclusao}</div> : null}</td>
                                <td className="num">{m.custo !== undefined && m.custo !== null ? formatarMoeda(m.custo) : "—"}</td>
                                <td><span className={`pill ${PILL_STATUS_MANUTENCAO[m.status]}`}>{ROTULO_STATUS_MANUTENCAO[m.status]}</span></td>
                                <td style={{ display: "flex", gap: 4, flexWrap: "wrap" }}>
                                  {m.status === "agendada" && (
                                    <button className="btn" style={{ padding: "3px 6px", fontSize: 12 }} onClick={() => iniciarManutencaoAgendada(m.id)}>
                                      Iniciar
                                    </button>
                                  )}
                                  {(m.status === "agendada" || m.status === "em_andamento") && (
                                    <>
                                      <button className="btn primary" style={{ padding: "3px 6px", fontSize: 12 }} onClick={() => abrirConclusaoManutencao(m)}>
                                        Concluir
                                      </button>
                                      <button className="btn danger" style={{ padding: "3px 6px", fontSize: 12 }} onClick={() => abrirCancelamentoManutencao(m.id)}>
                                        Cancelar
                                      </button>
                                    </>
                                  )}
                                </td>
                              </tr>
                              {concluindoId === m.id && (
                                <tr key={`${m.id}-concluir`}>
                                  <td colSpan={6} style={{ background: "var(--surface-2)" }}>
                                    <div style={{ display: "flex", gap: 10, alignItems: "flex-end", padding: "10px 4px", flexWrap: "wrap" }}>
                                      <label style={{ fontSize: 12, color: "var(--ink-soft)" }}>
                                        Data de conclusão
                                        <input type="date" className="btn" style={{ marginTop: 4 }} value={dataConclusao} onChange={(e) => setDataConclusao(e.target.value)} />
                                      </label>
                                      <label style={{ fontSize: 12, color: "var(--ink-soft)" }}>
                                        Custo final (R$)
                                        <input className="btn" style={{ cursor: "text", marginTop: 4, width: 120 }} value={custoConclusao} onChange={(e) => setCustoConclusao(e.target.value)} />
                                      </label>
                                      <button className="btn primary" disabled={!dataConclusao} onClick={confirmarConclusaoManutencao}>
                                        <Check size={13} /> Confirmar
                                      </button>
                                      <button className="btn" onClick={() => setConcluindoId(null)}>
                                        <X size={13} /> Cancelar
                                      </button>
                                    </div>
                                  </td>
                                </tr>
                              )}
                              {cancelandoManutencaoId === m.id && (
                                <tr key={`${m.id}-cancelar`}>
                                  <td colSpan={6} style={{ background: "var(--surface-2)" }}>
                                    <div style={{ display: "flex", gap: 10, alignItems: "flex-end", padding: "10px 4px", flexWrap: "wrap" }}>
                                      <label style={{ fontSize: 12, color: "var(--ink-soft)", flex: 1, minWidth: 200 }}>
                                        Motivo do cancelamento
                                        <input className="btn" style={{ cursor: "text", width: "100%", marginTop: 4 }} value={motivoCancelamentoManutencao} onChange={(e) => setMotivoCancelamentoManutencao(e.target.value)} />
                                      </label>
                                      <button className="btn danger" disabled={!motivoCancelamentoManutencao.trim()} onClick={confirmarCancelamentoManutencao}>
                                        <Check size={13} /> Confirmar
                                      </button>
                                      <button className="btn" onClick={() => setCancelandoManutencaoId(null)}>
                                        <X size={13} /> Voltar
                                      </button>
                                    </div>
                                  </td>
                                </tr>
                              )}
                            </>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  )}
                  <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(160px, 1fr))", gap: 6, marginBottom: 6 }}>
                    <input
                      className="btn" style={{ cursor: "text" }}
                      placeholder="Tipo * (ex: elétrica)"
                      value={rascunhoManutencao.tipo}
                      onChange={(e) => setRascunhoManutencao({ ...rascunhoManutencao, tipo: e.target.value })}
                    />
                    <input
                      className="btn" style={{ cursor: "text" }}
                      placeholder="Descrição *"
                      value={rascunhoManutencao.descricao}
                      onChange={(e) => setRascunhoManutencao({ ...rascunhoManutencao, descricao: e.target.value })}
                    />
                    <input
                      type="date" className="btn"
                      value={rascunhoManutencao.data_agendada}
                      onChange={(e) => setRascunhoManutencao({ ...rascunhoManutencao, data_agendada: e.target.value })}
                    />
                    <input
                      className="btn" style={{ cursor: "text" }}
                      placeholder="Custo estimado (R$)"
                      value={rascunhoManutencao.custo}
                      onChange={(e) => setRascunhoManutencao({ ...rascunhoManutencao, custo: e.target.value })}
                    />
                  </div>
                  <div style={{ display: "flex", gap: 6 }}>
                    <input
                      className="btn" style={{ cursor: "text", flex: 1 }}
                      placeholder="Observações"
                      value={rascunhoManutencao.observacoes}
                      onChange={(e) => setRascunhoManutencao({ ...rascunhoManutencao, observacoes: e.target.value })}
                    />
                    <button
                      className="btn"
                      disabled={rascunhoManutencao.tipo.trim() === "" || rascunhoManutencao.descricao.trim() === "" || !rascunhoManutencao.data_agendada}
                      onClick={adicionarManutencao}
                    >
                      <Plus size={13} /> Agendar
                    </button>
                  </div>
                </div>
              )}
            </div>
          )}

          <div style={{ display: "flex", gap: 8 }}>
            <button className="btn primary" disabled={form.apelido.trim() === ""} onClick={salvar}>
              Salvar
            </button>
            <button className="btn" onClick={() => setForm(null)}>Cancelar</button>
          </div>
        </div>
      )}

      <div className="table-wrap">
        <table className="data-table">
          <thead>
            <tr>
              <th>Apelido</th>
              <th>Tipo</th>
              <th>Cidade</th>
              <th>Matrícula</th>
              <th className="num">Valor venal</th>
              <th>Situação</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            {imoveis.map((i) => (
              <tr key={i.id}>
                <td>{i.apelido}</td>
                <td>{ROTULO_TIPO[i.tipo]}</td>
                <td>{i.cidade ?? "—"}</td>
                <td style={{ fontSize: 12.5, color: "var(--ink-soft)" }}>
                  {i.matricula ?? "—"}
                  {i.matricula_mae && <div>mãe: {i.matricula_mae}</div>}
                </td>
                <td className="num">{i.valor_venal_atual !== undefined && i.valor_venal_atual !== null ? formatarMoeda(i.valor_venal_atual) : "—"}</td>
                <td style={{ display: "flex", gap: 4, flexWrap: "wrap" }}>
                  {i.uso_pessoal === 1 && (
                    <span className="pill warning" title="Fora do DRE da atividade de locação">
                      <Home size={11} style={{ marginRight: 3, verticalAlign: -1 }} /> uso pessoal
                    </span>
                  )}
                  {i.regime_patrimonial === "gestao_terceiros" && (
                    <span className="pill" title={`Fora do patrimônio líquido — propriedade de ${i.proprietario_nome ?? "terceiro"}`}>
                      <Users size={11} style={{ marginRight: 3, verticalAlign: -1 }} /> terceiros{i.proprietario_nome ? `: ${i.proprietario_nome}` : ""}
                    </span>
                  )}
                  {i.regime_patrimonial === "proprio" && i.co_titular_nome && (
                    <span className="pill warning" title="Percentual de participação de cada titular ainda não confirmado — imóvel contando 100% no patrimônio líquido até você confirmar">
                      <Users size={11} style={{ marginRight: 3, verticalAlign: -1 }} /> copropriedade: {i.co_titular_nome}
                    </span>
                  )}
                  {i.uso_pessoal === 0 && i.regime_patrimonial === "proprio" && (
                    i.financiado === 1 ? <span className="pill">financiado</span> : <span className="pill good">rendimento</span>
                  )}
                </td>
                <td>
                  <button className="btn" style={{ padding: "4px 7px" }} onClick={() => abrirEdicao(i)}>
                    <Pencil size={13} />
                  </button>
                </td>
              </tr>
            ))}
            {imoveis.length === 0 && (
              <tr>
                <td colSpan={7} style={{ textAlign: "center", color: "var(--ink-soft)", padding: 24 }}>
                  Nenhum imóvel cadastrado ainda.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}
